basicCode.vanilla:
import { createMessageTiming } from '@/components/ui/message-timing';

createMessageTiming({
  stats: medidas,
  streaming: false,
  labels: rotulos,
});

withLabelsCode.web:
// TUDO CHEGA ESCRITO. Separador decimal, abreviatura de unidade e ordem das
// partes são decisão de idioma e de lugar — quem sabe disso é quem mediu, e
// não um componente que decidiria idioma em cinco lugares.
const duracao = (valor, unidade) =>
  new Intl.NumberFormat('pt-BR', {
    style: 'unit',
    unit: unidade,
    unitDisplay: 'short',
    maximumFractionDigits: 2,
  }).format(valor);

// A unidade vem de quem mediu, e não de um limiar do componente: quem
// cronometrou já sabe em que unidade a medida faz sentido.
const medidas = [
  { label: 'Primeiro token', value: duracao(420, 'millisecond') },
  { label: 'Total', value: duracao(1.24, 'second') },
  { label: 'Velocidade', value: '38,4 tok/s' },
  { label: 'Pedaços', value: '42' },
];

// E o texto da peça: de que medição se trata, e a palavra que avisa que ela
// ainda não acabou.
const rotulos = {
  title: 'Tempo desta resposta',
  measuring: 'Medindo',
};

extensibilityCode.web:
// QUANTAS MEDIDAS EXISTEM É DE QUEM MEDE. A peça desenha duas ou seis com a
// mesma chamada, e não reserva espaço para o que não veio:
const apenasOTotal = [{ label: 'Total', value: '1,24 s' }];

const tudoQueSeMediu = [
  { label: 'Primeiro token', value: '420 ms' },
  { label: 'Total', value: '1,24 s' },
  { label: 'Velocidade', value: '38,4 tok/s' },
  { label: 'Pedaços', value: '42' },
];

// SEM MEDIDA NENHUMA, a lista não é montada — e quem não mediu nada não monta
// a peça:
const nadaFoiMedido = [];

// NÃO HÁ CONTA A IMPORTAR. A velocidade já foi dividida por quem cronometrou,
// e a duração já foi escrita: o que atravessa é texto, e texto não passa por
// um primitivo de aritmética.

customizationCode.web:
.nds-message-timing {
  max-inline-size: 32rem;
}

/* O valor é quem se lê primeiro, e o termo é apoio. Mexer no peso não muda o
   que chega a quem ouve — a lista de definição já pareia os dois. */
.nds-message-timing-value {
  font-weight: var(--font-weight-semibold);
}

